                currentByteIndex = idx;
                currentByteOffset = offset;
                decodeReturn = lastRet;
                return FIT_FALSE;
            }
            checkPause = FIT_FALSE;

            lastRet = ReadByte((FIT_UINT8)buffer[idx]);

            if (lastRet != RETURN_CONTINUE)
            {
                switch (lastRet) {
                    case RETURN_MESG:
                    {
                        currentByteIndex = idx;
                        currentByteOffset = offset;
                        decodeReturn = lastRet;

                        FIT_MESG_NUM mesgNum = mesg.GetNum();
