                        ++offset;
                        currentByteIndex = idx;
                        currentByteOffset = offset;
                        decodeReturn = lastRet;
                        return FIT_TRUE;

                    default:
                        ++offset;
                        currentByteIndex = idx;
                        currentByteOffset = offset;
                        decodeReturn = lastRet;
                        return FIT_TRUE;
